<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ApiError } from '@/api/client'; import { createSource, getSources, type Source } from '@/api/sources'; import { getSession } from '@/api/session';
const router = useRouter(); const sources = ref<Source[]>([]); const lock = ref<string | null>(null); const error = ref<string | null>(null); const form = ref({ nombre: '', description: '' }); const creating = ref(false);
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'coordinador') { await router.replace('/panel'); return; } const response = await getSources(); sources.value = response.sources; lock.value = response.processLock; } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudieron cargar las fuentes.'; } };
const create = async () => { try { creating.value = true; const source = await createSource({ nombre: form.value.nombre, description: form.value.description || undefined }); await router.push(`/coordinacion/fuentes/${source.source_id}`); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo crear la fuente.'; } finally { creating.value = false; } };
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Coordinación</p><h1>Fuentes académicas</h1><p>Documentos Markdown que respaldan las recomendaciones de IA.</p></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><p v-if="lock" role="alert">{{ lock }}</p><p v-if="error" role="alert">{{ error }}</p><section class="detail-card"><h2>Nueva fuente</h2><form class="editor-form" @submit.prevent="create"><label>Nombre<input v-model="form.nombre" required maxlength="180" :disabled="Boolean(lock)" /></label><label>Descripción<textarea v-model="form.description" maxlength="2000" :disabled="Boolean(lock)" /></label><button :disabled="creating || Boolean(lock)">{{ creating ? 'Creando…' : 'Crear fuente' }}</button></form></section><section class="detail-card"><h2>Fuentes de la carrera</h2><div v-if="sources.length" class="table-wrap"><table><thead><tr><th>Nombre</th><th>Contenido</th><th></th></tr></thead><tbody><tr v-for="source in sources" :key="source.id"><td><strong>{{ source.name }}</strong><small>{{ source.description }}</small></td><td>{{ source.has_content ? 'Redactada' : 'Pendiente' }}</td><td><RouterLink class="back-link" :to="`/coordinacion/fuentes/${source.id}`">Editar</RouterLink></td></tr></tbody></table></div><p v-else class="empty-state">Todavía no hay fuentes académicas.</p></section></main></template>
